#!/usr/bin/env php
<?php
/**
 * # Parameters
 * ```
 * --overwrite_existing_installation
 * --skip_db_integrity_check
 * --skip_read_workspace_files
 * --dont_create_sample_data
 * ```
 */

if (php_sapi_name() !== 'cli') {
  header('HTTP/1.0 403 Forbidden');
  echo "This is only for usage from command line.";
  exit(1);
}

ini_set('memory_limit', '1G');

define('ROOT_DIR', realpath(__DIR__ . '/..'));
const DATA_DIR = ROOT_DIR . '/data';

require_once "vendor/autoload.php";

try {
  SystemConfig::applyVersionFromPackageJson();
  $systemVersion = SystemConfig::$system_version;
  CLI::h1("IQB TESTCENTER BACKEND $systemVersion");

  if (file_exists(ROOT_DIR . '/backend/config/init.lock')) {
    throw new InvalidArgumentException("Initialize is already running.");
  }
  if (file_exists(ROOT_DIR . '/backend/config/error.lock')) {
    $msg = file_get_contents(ROOT_DIR . '/backend/config/error.lock');
    unlink(ROOT_DIR . '/backend/config/error.lock');
    CLI::warning("Last initialize failed with error: $msg.");
    CLI::warning("Trying again:");
  }
  file_put_contents(ROOT_DIR . '/backend/config/init.lock', '.');

  $opt = CLI::getOpt();
  $args = [
    'overwrite_existing_installation' => isset($opt['overwrite_existing_installation']),
    'skip_db_integrity_check' => isset($opt['skip_db_integrity_check']),
    'skip_read_workspace_files' => isset($opt['skip_read_workspace_files']),
    'dont_create_sample_data' => isset($opt['dont_create_sample_data'])
  ];

  if (count($opt)) {
    CLI::h2("Initialization Options:");
    foreach ($args as $arg => $isset) {
      if ($isset) {
        CLI::p(" * $arg");
      }
    }
  }

  CLI::h2("System-Config");
  try {
    SystemConfig::readEnvironment();
    CLI::connectDBWithRetries();
    SystemConfig::writeConfigIni();
    CLI::success("New config file created at `/backend/config/config.ini`.");
  } catch (Exception $e) {
    CLI::warning("Failed to write new config file:" . $e->getMessage());
    if (!file_exists(ROOT_DIR . '/backend/config/config.ini')) {
      throw new Exception("No Config file found at `/backend/config/config.ini`!");
    }
    SystemConfig::readConfigIni();
    CLI::connectDBWithRetries();
    CLI::success("Config file found at `/backend/config/config.ini`.");
  }

  CLI::h2("Check Database Settings");
  $initDAO = new InitDAO();
  if (!$initDAO->checkSQLMode()) {
    throw new Exception('SQLMode is not set properly. Check the config and restart.');
  }
  CLI::success("SQL-Mode seems to be OK.");

  CLI::h2("Database Structure");

  $dbStatus = $initDAO->getDbStatus();
  CLI::p("Database status: {$dbStatus['message']}");

  if ($args['overwrite_existing_installation']) {
    CLI::warning("Clear database");
    $tablesDropped = $initDAO->clearDB();
    CLI::p("Tables dropped: " . implode(', ', $tablesDropped));
  }

  if ($args['overwrite_existing_installation'] or ($dbStatus['tables'] == 'empty')) {
    CLI::p("Install basic database structure");
    $initDAO->runFile(ROOT_DIR . "/scripts/database/base.sql");
  }

  $dbSchemaVersion = $initDAO->getDBSchemaVersion();
  $isCurrentVersion = Version::compare($dbSchemaVersion); // 1 : System is older than DB!, -1 : DB is outdated
  CLI::p("Database schema version is $dbSchemaVersion, system version is $systemVersion");
  if ($isCurrentVersion >= 0) {
    echo ": O.K.";

  } else {
    CLI::p("Install patches if necessary");
    $allowFailing = (in_array($dbSchemaVersion, ['0.0.0-no-table', '0.0.0-no-value']));
    $patchInstallReport = $initDAO->installPatches(ROOT_DIR . "/scripts/database/patches.d", $allowFailing);
    foreach ($patchInstallReport['patches'] as $patch) {
      if (isset($patchInstallReport['errors'][$patch])) {
        CLI::warning("* $patch: {$patchInstallReport['errors'][$patch]}");

      } else {
        CLI::success("* $patch: installed successfully.");
      }
    }
    if (count($patchInstallReport['errors']) and !$allowFailing) {
      throw new Exception('Installing database patches failed.');
    }
  }

<?php

declare(strict_types=1);

use DI\Container;
use Slim\Factory\AppFactory;
use Slim\Http\Response;
use Slim\Http\ServerRequest as Request;

// local function to react correctly even if autoloader is broken
function fatalErrorHandler(Throwable $e): void {
  // this can only happen if slim itself or slim error handler fails or some class fails in constructor
  http_response_code(500);
  $id = uniqid('fatal-', true);
  header('Error-ID:' . $id);
  error_log("$id (500) at {$e->getFile()}:{$e->getLine()}");
  error_log($e->getMessage());
  $path = explode('/', $e->getFile());
  echo "Fatal error (500) at {$path[count($path)-2]}/{$path[count($path)-1]}:{$e->getLine()} : {$e->getMessage()}";
}


try {
  ini_set('display_errors', '0');
  ini_set('display_startup_errors', '0');
  register_shutdown_function(function() {
    $e = error_get_last();
    if(!is_null($e) and in_array($e['type'], [E_ERROR, E_COMPILE_ERROR, E_CORE_ERROR])) {
      fatalErrorHandler(new ErrorException($e['message'], 1, 1, $e['file'], $e['line']));
    }
  });

  define('ROOT_DIR', realpath(dirname(__FILE__) . '/../'));

  require_once "vendor/autoload.php";

  // TODO move this to .htaccess
  if (($_SERVER['REQUEST_METHOD'] !== 'OPTIONS') and file_exists(ROOT_DIR . '/backend/config/error.lock')) {
    throw new Exception("Service could not be started correctly! Please refer to your system administrator.");
  }

  // TODO move this to .htaccess
  if (($_SERVER['REQUEST_METHOD'] !== 'OPTIONS') and file_exists(ROOT_DIR . '/backend/config/init.lock')) {
    http_response_code(503);
    header('Retry-After:30');
    echo "Service is restarting.";
    exit;
  }

  SystemConfig::readConfigIni();

  if (isset($_SERVER['HTTP_TESTMODE'])) {
    error_log("{$_SERVER['HTTP_TESTMODE']}: [{$_SERVER['REQUEST_METHOD']}] {$_SERVER['REQUEST_URI']}");
    TestEnvironment::setup($_SERVER['HTTP_TESTMODE'], $_SERVER['HTTP_TESTCLOCK'] ?? null);
  } else { // productive
    define('DATA_DIR', ROOT_DIR . '/data');
    date_default_timezone_set(SystemConfig::$system_timezone); // just to be safe. TimeStamp-class should be used everywhere anyway
    DB::connect();
  }

  $container = new Container();
  AppFactory::setContainer($container);
  $app = AppFactory::create();

  $app->addRoutingMiddleware();
  $errorMiddleware = $app->addErrorMiddleware(true, true, true);
  $errorHandler = new ErrorHandler();
  $errorMiddleware->setDefaultErrorHandler($errorHandler);

  $projectPath = Server::getProjectPath();
  if ($projectPath) {
    $app->setBasePath($projectPath);
  }

  $app->options('/{routes:.+}', function(Request $request, Response $response): Response {
    return $response;
  });

  include_once 'routes.php';

  $app->any('/{path:.*}', function (Request $request, Response $response): Response {
    return $response
      ->withStatus(404);
  });

  $app->run();

} catch (Throwable $e) {
  fatalErrorHandler($e);
}
# Base compose file defining services and their settings
# For concrete images check the environment specific override files.

x-restart-policy: &restart-policy
  restart: "${RESTART_POLICY:-always}"

x-env-redis: &env-redis
  REDIS_HOST: cache-server
  REDIS_PORT: 6379
  REDIS_PASSWORD: ${REDIS_PASSWORD}
  REDIS_CACHE_FILES: ${REDIS_CACHE_FILES:-false}

x-env-mysql: &env-mysql
  MYSQL_DATABASE: ${MYSQL_DATABASE}
  MYSQL_USER: ${MYSQL_USER}
  MYSQL_PASSWORD: ${MYSQL_PASSWORD}

x-env-logging-conf: &env-logging-conf
  max-size: "200m"
  max-file: "10"

services:
  traefik:
    image: ${DOCKERHUB_PROXY}traefik:v3.6
    <<: *restart-policy
    ports:
      - "${HTTP_PORT:-80}:80"
    volumes:
      - "/var/run/docker.sock:/var/run/docker.sock:ro"
    networks:
      testcenter:

  broadcaster:
    image: iqbberlin/testcenter-broadcaster:current
    <<: *restart-policy
    logging:
      options:
        <<: *env-logging-conf
    networks:
      testcenter:

  frontend:
    image: iqbberlin/testcenter-frontend:current
    <<: *restart-policy
    depends_on:
      backend:
        condition: service_healthy
    logging:
      options:
        <<: *env-logging-conf
    networks:
      testcenter:


  file-server:
    image: iqbberlin/testcenter-file-server:current
    <<: *restart-policy
    depends_on:
      - cache-server
    environment:
      <<: *env-redis
    volumes_from:
      - backend:ro
    networks:
      testcenter:

  backend:
    image: iqbberlin/testcenter-backend:current
    <<: *restart-policy
    depends_on:
      db:
        condition: service_healthy
      cache-server:
        condition: service_started
    environment:
      BROADCASTER_ENABLED: ${BROADCASTER_ENABLED}
      FILE_SERVER_ENABLED: ${FILE_SERVER_ENABLED}
      BRUTE_FORCE_PROTECTION: ${BRUTE_FORCE_PROTECTION:-}
      <<: [ *env-redis, *env-mysql ]
      MYSQL_HOST: db
      MYSQL_PORT: 3306
      PASSWORD_SALT: ${PASSWORD_SALT}
      PASSWORD_MIN_LENGTH: ${PASSWORD_MIN_LENGTH}
      PASSWORD_PATTERN: ${PASSWORD_PATTERN}
      ADMIN_INIT_PASSWORD: ${ADMIN_INIT_PASSWORD}
    logging:
      options:
        <<: *env-logging-conf
    healthcheck:
      test: [ "CMD", "curl", "-f", "http://backend:8080/version" ]
      start_period: 600s
      start_interval: 5s
      interval: 90s
      timeout: 30s
      retries: 3
    volumes:
      - backend_vol:/var/www/testcenter/data
      - /var/www/testcenter/data/.schemas
    networks:
      testcenter:

  cache-server:
    image: ${DOCKERHUB_PROXY}redis:8.0-bookworm
    <<: *restart-policy
    user: redis
    command: [
      "redis-server",
      "--requirepass", "${REDIS_PASSWORD}",
      "--maxmemory", "${REDIS_MEMORY_MAX:-1gb}",
      "--maxmemory-policy", "volatile-lru",
      "--save", '""',
      "--appendonly", "no"
    ]
    networks:
      testcenter:

  db:
    image: ${DOCKERHUB_PROXY}mysql:8.4
    <<: *restart-policy
    environment:
      <<: *env-mysql
      MYSQL_ROOT_PASSWORD: ${MYSQL_ROOT_PASSWORD}
      MYSQL_INITDB_SKIP_TZINFO: 'true'
    volumes:
      - db_vol:/var/lib/mysql
    healthcheck:
      test: [ "CMD", "mysqladmin", "ping", "--user", "${MYSQL_USER}", "-h", "127.0.0.1", "--silent" ]
      start_period: 120s
      start_interval: 5s
      interval: 90s
      timeout: 30s
      retries: 3
    networks:
      testcenter:

volumes:
  db_vol:
  backend_vol:

networks:
  testcenter:
    name: testcenter
    driver: bridge
    driver_opts:
      com.docker.network.driver.mtu: ${DOCKER_DAEMON_MTU:-1500}
# Compose file for local development and testing. Images are built from
# local directories which need to be cloned from the repository.

services:
  traefik:
    labels:
      - "traefik.enable=true"
      - "traefik.http.routers.traefik.rule=Host(`traefik.${HOSTNAME}`)"
      - "traefik.http.routers.traefik.service=api@internal"
      - "traefik.http.middlewares.security-headers.headers.stsSeconds=63072000"
      - "traefik.http.middlewares.security-headers.headers.stsIncludeSubdomains=true"
      - "traefik.http.middlewares.security-headers.headers.stsPreload=true"
      - "traefik.http.middlewares.security-headers.headers.forceSTSHeader=true"
      - "traefik.http.middlewares.security-headers.headers.REDACTED"
      - "traefik.http.middlewares.security-headers.headers.contentTypeNosniff=true"
      - "traefik.http.middlewares.security-headers.headers.browserXssFilter=true"
      - "traefik.http.middlewares.security-headers.headers.referrerPolicy=no-referrer"
    command:
      - "--log.level=INFO"
      - "--accesslog=false"
      - "--api.dashboard=true"
      - "--api.insecure=true"
      - "--providers.docker=true"
      - "--providers.docker.exposedbydefault=false"
    networks:
      - testcenter

  broadcaster:
    build:
      dockerfile: broadcaster/Dockerfile
      target: dev
      args:
        REGISTRY_PATH: ${DOCKERHUB_PROXY}
    volumes:
      - ./common:/usr/src/testcenter/common
      - ./broadcaster/src:/usr/src/testcenter/broadcaster/src
    networks:
      - testcenter

  frontend:
    labels:
      - "traefik.enable=true"
      - "traefik.http.routers.frontend.rule=Host(`www.${HOSTNAME}`) || Host(`${HOSTNAME}`)"
      - "traefik.http.routers.frontend.middlewares=security-headers, stripwww-fe"
      - "traefik.http.middlewares.stripwww-fe.redirectregex.regex=^http(s?)://www.${HOSTNAME}/(.*)"
      - "traefik.http.middlewares.stripwww-fe.redirectregex.replacement=http$${1}://${HOSTNAME}/$${2}"
    build:
      dockerfile: frontend/Dockerfile
      target: dev
      args:
        REGISTRY_PATH: ${DOCKERHUB_PROXY}
    command: [
      "serve",
      "--configuration", "dev",
      "--host", "0.0.0.0",
      "--port", "8080"
    ]
    volumes:
      - ./common:/usr/src/testcenter/common
      - ./definitions:/usr/src/testcenter/definitions
      - ./frontend/src:/usr/src/testcenter/frontend/src
      - ./docs/dist:/usr/src/testcenter/docs/dist
    networks:
      - testcenter

  file-server:
    build:
      dockerfile: file-server/Dockerfile
      args:
        REGISTRY_PATH: ${DOCKERHUB_PROXY}
        ENABLED_MODULES: lua
    volumes:
      - ./sampledata/sample_resource_package.itcr.zip:/var/www/testcenter/data-TEST/ws_1/Resource/sample_resource_package.itcr.zip
      - ./sampledata/SAMPLE_UNITCONTENTS.HTM:/var/www/testcenter/data-TEST/ws_1/Resource/SAMPLE_UNITCONTENTS.HTM
      - ./sampledata/verona-player-simple-6.0.html:/var/www/testcenter/data-TEST/ws_1/Resource/verona-player-simple-6.0.html
      - ./sampledata/coding-scheme.vocs.json:/var/www/testcenter/data-TEST/ws_1/Resource/coding-scheme.vocs.json
      - ./file-server/nginx.conf:/etc/nginx/nginx.conf
      - ./file-server/auth/:/usr/share/nginx/auth
      - ./file-server/cors.conf:/etc/nginx/conf.d/cors.conf
    networks:
      - testcenter

  backend:
    build:
      dockerfile: backend/Dockerfile
      target: dev
      args:
        REGISTRY_PATH: ${DOCKERHUB_PROXY}
    volumes:
      - ./backend/.htaccess:/var/www/testcenter/backend/.htaccess
      - ./backend/config/docker-php-ext-xdebug.ini:/usr/local/etc/php/conf.d/docker-php-ext-xdebug.ini
      - ./backend/config/local.php.ini:/usr/local/etc/php/conf.d/local.ini
      - ./backend/config/no-cors.htaccess/:/var/www/testcenter/.htaccess
      - ./backend/config/vhost.conf:/etc/apache2/sites-available/vhost.conf
      - ./backend/index.php:/var/www/testcenter/backend/index.php
      - ./backend/initialize.php:/var/www/testcenter/backend/initialize.php
      - ./backend/routes.php:/var/www/testcenter/backend/routes.php
      - ./backend/src:/var/www/testcenter/backend/src
      - ./backend/test:/var/www/testcenter/backend/test
      - ./backend/mago.toml:/var/www/testcenter/backend/mago.toml:ro
      - ./definitions:/var/www/testcenter/definitions
      - ./docs/dist:/docs/dist
      - ./package.json:/var/www/testcenter/package.json
      - ./sampledata:/var/www/testcenter/sampledata
      - ./scripts/database:/var/www/testcenter/scripts/database
    environment:
      SKIP_READ_FILES: ${SKIP_READ_FILES:-no}
      SKIP_DB_INTEGRITY: ${SKIP_DB_INTEGRITY:-no}
      OVERWRITE_INSTALLATION: ${OVERWRITE_INSTALLATION:-no}
      NO_SAMPLE_DATA: ${NO_SAMPLE_DATA:-no}
    ports:
      - "9005:9003"
    extra_hosts:
      - "host.docker.internal:host-gateway"
    networks:
      - testcenter

  cache-server:
    ports:
      - "6379:6379"

  db:
    ports:
      - "9091:3306"
    command:
      - "--explicit-defaults-for-timestamp=TRUE"
      - "--sql-mode=PIPES_AS_CONCAT,ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION"
      - "--tls-version=TLSv1.2,TLSv1.3"
      - "--max-connections=500"
      - "--log_error_verbosity=2"
      - "--binlog-expire-logs-seconds=${MYSQL_BINLOG_EXPIRE_LOGS_SECONDS:-2592000}"
    volumes:
      - ./scripts/database/000-create-test-db.sh:/docker-entrypoint-initdb.d/000-create-test-db.sh
    networks:
      - testcenter
